BackgroundColor3 = BUTTONFrame.BorderSizePixel = 0Frame.Parent = pagelocal Corner = Instance.new("UICorner")Corner.CornerRadius = UDim.new(0, 6)Corner.Parent = Framelocal Label = Instance.new("TextLabel")Label.Size = UDim2.new(1, -20, 0, 25)Label.Position = UDim2.fromOffset(10, 2)Label.BackgroundTransparency = 1Label.Text = text .. ": " .. tostring(default)Label.TextColor3 = TEXTLabel.TextSize = 13Label.Font = Enum.Font.GothamLabel.TextXAlignment = Enum.TextXAlignment.LeftLabel.Parent = Framelocal SliderBg = Instance.new("TextButton")SliderBg.Size = UDim2.new(1, -20, 0, 6)SliderBg.Position = UDim2.fromOffset(10, 35)SliderBg.BackgroundColor3 = Color3.fromRGB(45, 45, 48)SliderBg.BorderSizePixel = 0SliderBg.Text = ""SliderBg.AutoButtonColor = falseSliderBg.Parent = Framelocal SliderBar = Instance.new("Frame")SliderBar.Size = UDim2.fromScale((default - min) / (max - min), 1)SliderBar.BackgroundColor3 = Color3.fromRGB(135, 150, 255)SliderBar.BorderSizePixel = 0SliderBar.Parent = SliderBglocal function updateSlider(input)local percentage = math.clamp((input.Position.X - SliderBg.AbsolutePosition.X) / SliderBg.AbsoluteSize.X, 0, 1)SliderBar.Size = UDim2.fromScale(percentage, 1)local value = math.round(min + (percentage * (max - min)))Label.Text = text .. ": " .. tostring(value)callback(value)endlocal dragging = falseSliderBg.InputBegan:Connect(function(input)if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch thendragging = trueupdateSlider(input)endend)UserInputService.InputChanged:Connect(function(input)if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) thenupdateSlider(input)endend)UserInputService.InputEnded:Connect(function(input)if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch thendragging = falseendend)end--==================================================-- СОЗДАНИЕ ВКЛАДОК И СВЯЗЫВАНИЕ ИНТЕРФЕЙСА--==================================================local function registerTab(name, order)local Tab = Instance.new("TextButton")Tab.Name = name .. "Tab"Tab.Size = UDim2.new(1, 0, 0, 36)Tab.LayoutOrder = orderTab.BackgroundColor3 = Color3.fromRGB(18, 18, 19)Tab.BorderSizePixel = 0Tab.Text = nameTab.TextColor3 = SUBTEXTTab.TextSize = 13Tab.Font = Enum.Font.GothamMediumTab.AutoButtonColor = falseTab.Parent = Sidebarlocal TabCorner = Instance.new("UICorner")TabCorner.CornerRadius = UDim.new(0, 7)TabCorner.Parent = Tablocal Accent = Instance.new("Frame")Accent.Size = UDim2.fromOffset(3, 24)Accent.Position = UDim2.fromOffset(0, 6)Accent.BackgroundColor3 = Color3.fromRGB(135, 150, 255)Accent.BorderSizePixel = 0Accent.Visible = falseAccent.Parent = TabTabs[name] = {Button = Tab, Accent = Accent}endlocal function selectTab(name)for tName, tObj in pairs(Tabs) doif tName == name thentObj.Button.BackgroundColor3 = Color3.fromRGB(29, 29, 31)tObj.Button.TextColor3 = TEXTtObj.Accent.Visible = truePages[tName].Visible = trueelsetObj.Button.BackgroundColor3 = Color3.fromRGB(18, 18, 19)tObj.Button.TextColor3 = SUBTEXTtObj.Accent.Visible = falsePages[tName].Visible = falseendendend-- Регистрация Combat и VisualsregisterTab("Combat", 1)registerTab("Visuals", 2)local combatPage = createPage("Combat")local visualsPage = createPage("Visuals")-- Инициализируем вкладку по умолчаниюTabs["Combat"].Button.MouseButton1Click:Connect(function() selectTab("Combat") end)Tabs["Visuals"].Button.MouseButton1Click:Connect(function() selectTab("Visuals") end)selectTab("Combat")--==================================================-- НАПОЛНЕНИЕ НАСТРОЙКАМИ (UI CONTROLS)--==================================================-- CombatcreateCheckbox(combatPage, "Включить Aimbot (Instant Snap)", function(v)Settings.Combat.Aimbot = vFovCircle.Visible = (v or Settings.Combat.FlickBot)end)createCheckbox(combatPage, "Включить AimFlickBot (При нажатии выстрела)", function(v)Settings.Combat.FlickBot = vFovCircle.Visible = (v or Settings.Combat.Aimbot)end)createSlider(combatPage, "Радиус прицеливания (FOV)", 10, 900, Settings.Combat.Fov, function(v)Settings.Combat.Fov = vFovCircle.Radius = vend)createCheckbox(combatPage, "Глобальный WallCheck (Стены)", function(v)Settings.Combat.WallCheck = vend)-- VisualscreateCheckbox(visualsPage, "Включить 2D ESP", function(v) Settings.Visuals.ESP = v end)createCheckbox(visualsPage, "Включить Модели (Charms)", function(v) Settings.Visuals.Charms = v end)--==================================================-- ЛОГИКА ХАКОВ (WALLCHECK, AIMBOT, ESP, CHARMS)--==================================================-- Функция проверки препятствий между камерой и головой противникаlocal function IsVisible(targetPart)if not Settings.Combat.WallCheck then return true endif not targetPart then return false endlocal castRay = Ray.new(camera.CFrame.Position, (targetPart.Position - camera.CFrame.Position).Unit * 1000)local hit, position = Workspace:FindPartOnRayWithIgnoreList(castRay, {player.Character, targetPart.Parent})return hit == nilend-- Поиск ближайшей валидной цели в радиусе FOVlocal function GetClosestTarget()local closestTarget = nillocal shortestDistance = math.hugefor _, v in pairs(Players:GetPlayers()) doif v ~= player and v.Character and v.Character:FindFirstChild("Head") and v.Character:FindFirstChildOfClass("Humanoid") and v.Character.Humanoid.Health > 0 thenlocal head = v.Character.Head-- Проверка WallCheck для аимаif IsVisible(head) thenlocal screenPos, onScreen = camera:WorldToViewportPoint(head.Position)if onScreen thenlocal mousePos = UserInputService:GetMouseLocation()local distance = (Vector2.new(screenPos.X, screenPos.Y) - mousePos).Magnitudeif distance < Settings.Combat.Fov and distance < shortestDistance thenclosestTarget = headshortestDistance = distanceendendendendendreturn closestTargetend-- Логика постоянного обновления кадровlocal isShooting = false-- Проверка нажатия выстрела/касания для FlickBotUserInputService.InputBegan:Connect(function(input, processed)if processed then return endif input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch thenisShooting = trueendend)UserInputService.InputEnded:Connect(function(input)if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch thenisShooting = falseendend)-- Рендер ESP и обновление FOV кольца в реальном времениlocal espObjects = {}RunService.RenderStepped:Connect(function()-- Обновление позиции круга FOV за мышкойlocal mouseLocation = UserInputService:GetMouseLocation()FovCircle.Position = mouseLocation-- Обработка Аимботовlocal target = GetClosestTarget()i
